"""Write results.md of experiment 18 from results/results.json. Usage: python make_report18.py results/results.json results.md"""
import json, sys
r = json.load(open(sys.argv[1])); L = r['labels']; T = r['test_on_75_humans']; C = r['test_on_75_humans_ci95']; P = r['paired_on_75_humans']; A = r['audit']
meths = list(L); ctl_b = r['control_b_train_G01_G10_AI_labels']; ca = r['control_a_fit_on_75_humans_only_20_5_splits_rps']
f = lambda mt, m, d=4: f"{T[mt][m]:.{d}f}" + (f" [{C[mt][m][0]:.{d}f}, {C[mt][m][1]:.{d}f}]" if C[mt][m] else '')
def pr(mt, x, y, d=4):
    v = P[f'{mt}: {x} minus {y}']
    if v['ci95'] is None or v['point'] != v['point']: return 'undefined'
    return f"{v['point']:+.{d}f} [{v['ci95'][0]:+.{d}f}, {v['ci95'][1]:+.{d}f}]" + ('' if v['excludes_zero'] else ' (includes 0)')
w = r['weights']; wf = lambda m: '/'.join(f'{x:.2f}' for x in w[m]) if isinstance(w[m], list) else '-'
o = ['# Experiment 18 results (big-data version 1): fit on the large AI-labelled pool, test on the 75 human-rated artifacts', '',
     '**Doc link:** <https://github.com/brando90/trustworthy-theorem-judges/blob/main/experiments/archive/18_train_judges_on_591_ai_rated_outputs_test_on_75_human_rated_outputs/results.md>', '',
     f"**TLDR:** Fitting on {r['n_pool_items']} AI-labelled artifacts (50 fresh tasks) and testing on the 75 human-rated ones: the loss-fitted mixture (④, RPS {T['rps']['ce_mixture']:.4f}) beats the correlation-fitted mixture (②, {T['rps']['corr_mixture_pearson']:.4f}) (RPS difference ④ minus ② {pr('rps', 'ce_mixture', 'corr_mixture_pearson')}), but neither beats the untrained equal-weight mixture ({T['rps']['equal_mixture']:.4f}), and training on the 75 humans themselves does better ({ca['metrics']['ce_mixture']['point']:.4f}). The pool fits put most weight on the H0 Opus judge, which is the worst single config on humans. Cached judges, CPU only, no model calls, $0.", '',
     'Harness and models: no LLM in the loop for this run. The four candidate judges are cached outputs of the VeriBench experiment 106 runs: ' + '; '.join(f"{k}: {v}" for k, v in r['configs'].items()) + '. Their outputs on both the fresh pool and the 75 come from the same runs (3 repeats; some pool items have 2). The AI-rater labels are the saved `score_0_5` cells of the six rater families in the checkout (experiment 106 Valkyrie `vb106_rater_v2`; astra, fable51, grok47, kimik3, mimo26pro, qwen38max; the seventh, argon, is not in the checkout). The fitting script was written and run in Claude Code (Sonnet 5.5).', '',
     '## Data', '',
     f"- Pool: {A['fresh_used']} fresh non-blank artifacts, {r['n_pool_tasks']} tasks, none shared with the 25 test tasks. Label per artifact: histogram of its AI-rater scores (0 to 5), pooled over families, personas and repeats; cells per item min {A['ai_cells_per_fresh_item_min_median_max'][0]}, median {A['ai_cells_per_fresh_item_min_median_max'][1]:.0f}, max {A['ai_cells_per_fresh_item_min_median_max'][2]}. In experiment 106's leave-one-agent-out design each fresh item was rated by only about two families, so labels are noisier than the 75's.",
     f"- Test: the 75 human-rated artifacts, 25 tasks, 195 expert ratings, never used for fitting or choosing. Mean rating (0 to 1): humans {r['human_vs_ai_mean_rating_gap_on_75']['human_mean']:.3f}, AI panel on the same 75 {r['human_vs_ai_mean_rating_gap_on_75']['ai_panel_mean']:.3f}, AI labels of the pool {r['human_vs_ai_mean_rating_gap_on_75']['pool_ai_mean']:.3f}.",
     f"- Intervals: {r['bootstrap_draws']:,} joint bootstrap draws that resample pool tasks (and refit everything) and test tasks together.", '',
     '## Test on the 75 human-rated artifacts (point [95% interval])', '', '| Method | weights on H0_sol/H0_opus/H2_sol/H2_opus | RPS (main) | CE | TVD | Pearson | Spearman |', '|---|---|---|---|---|---|---|']
for m in meths: o.append((f"| {L[m]} | {wf(m)} | {f('rps', m)} | {f('ce', m, 3)} | {f('tvd', m)} | {f('pearson', m, 3)} | {f('spearman', m, 3)} |").replace('nan', 'undefined'))
o += ['', 'Pearson and Spearman are undefined for the constant forecast. Reference rows (not fitted, not deployable): each cached judge alone on the 75, and the AI panel\'s own label distribution as a forecast of the human distribution on the same 75.', '', '| Reference | RPS | CE | TVD | Pearson | Spearman |', '|---|---|---|---|---|---|']
for c, v in r['single_judges_on_75_humans'].items(): o.append(f"| judge {c} alone | {v['rps']:.4f} | {v['ce']:.3f} | {v['tvd']:.4f} | {v['pearson']:.3f} | {v['spearman']:.3f} |")
v = r['ai_panel_label_as_forecast_of_humans_on_75']; o.append(f"| AI panel label of the same 75 as forecast | {v['rps']:.4f} | {v['ce']:.3f} | {v['tvd']:.4f} | {v['pearson']:.3f} | {v['spearman']:.3f} |")
o += ['', '## Paired differences on the 75 (first minus second; negative = first better for RPS, CE, TVD)', '', '| Comparison | RPS | CE | Pearson | Spearman |', '|---|---|---|---|---|']
for x, y in [('ce_mixture', 'corr_mixture_pearson'), ('rps_mixture', 'corr_mixture_pearson'), ('ce_mixture', 'corr_mixture_spearman'), ('ce_mixture', 'equal_mixture'), ('corr_mixture_pearson', 'equal_mixture'), ('ce_mixture', 'constant')]:
    o.append(f"| {L[x]} minus {L[y]} | {pr('rps', x, y)} | {pr('ce', x, y, 3)} | {pr('pearson', x, y, 3)} | {pr('spearman', x, y, 3)} |")
o += ['', '## Controls', '',
      f"**(a) Fit on the 75 humans only** (same four configs, experiment 12's 20/5 task splits, {ca['splits']} splits, RPS on test tasks): " + '; '.join(f"{m} {ca['metrics'][m]['point']:.4f}" for m in ['constant', 'equal_mixture', 'corr_mixture_pearson', 'ce_mixture', 'rps_mixture']) + f". ④ minus ②: {ca['ce_mixture minus corr_mixture_pearson']['point']:+.4f} [{ca['ce_mixture minus corr_mixture_pearson']['ci95'][0]:+.4f}, {ca['ce_mixture minus corr_mixture_pearson']['ci95'][1]:+.4f}]; ④ minus equal weights: {ca['ce_mixture minus equal_mixture']['point']:+.4f} [{ca['ce_mixture minus equal_mixture']['ci95'][0]:+.4f}, {ca['ce_mixture minus equal_mixture']['ci95'][1]:+.4f}].",
      '', f"**(b) Label shift versus judge quality.** Fit on groups G01 to G10 ({ctl_b['n_train']} items), score against AI labels of held-out fresh groups G11 to G13 ({ctl_b['n_heldout_fresh']} items), against the AI labels of the 75, and against the human labels of the 75 (RPS; fitted on the 441 only, single fit, no interval):", '',
      '| Method | held-out fresh, AI labels | the 75, AI labels | the 75, human labels |', '|---|---|---|---|']
for m in ['constant', 'equal_mixture', 'corr_mixture_pearson', 'ce_mixture', 'rps_mixture']: o.append(f"| {L[m]} | {ctl_b['rps_on_heldout_fresh_AI_labels'][m]:.4f} | {ctl_b['rps_on_75_AI_labels'][m]:.4f} | {ctl_b['rps_on_75_human_labels'][m]:.4f} |")
o += ['', '## Plain reading', '',
      f"- Loss beats correlation, narrowly: the ④ CE mixture is ahead of the ② Pearson mixture on RPS ({pr('rps', 'ce_mixture', 'corr_mixture_pearson')}), CE and TVD, and level on Pearson and Spearman. Against the Spearman-fitted mixture the RPS interval includes 0. This matches the guess I gave earlier (loss ahead on RPS), with a small gap.",
      f"- Big data from AI labels did not help against humans. Both fitted mixtures are worse than the equal-weight average of the four judges ({T['rps']['equal_mixture']:.4f}); ④ minus equal is {pr('rps', 'ce_mixture', 'equal_mixture')}. Fitting on the 75 human-rated artifacts themselves gave {ca['metrics']['ce_mixture']['point']:.4f}, better than either pool-fitted mixture.",
      f"- Why, as far as the numbers show: the AI raters score these artifacts higher than humans (pool mean {r['human_vs_ai_mean_rating_gap_on_75']['pool_ai_mean']:.2f}, humans {r['human_vs_ai_mean_rating_gap_on_75']['human_mean']:.2f}) and the fits put most weight on the H0 Opus judge, which gets {w['ce_mixture'][1]:.0%} of the weight in ④ and {w['corr_mixture_pearson'][1]:.0%} in ②, although H0 Opus alone is the worst config against humans (RPS {r['single_judges_on_75_humans']['H0_opus']['rps']:.3f}) and H2 Opus the best (RPS {r['single_judges_on_75_humans']['H2_opus']['rps']:.3f}). Control (b) shows the same fits do well against AI labels (RPS about 0.075 on held-out fresh items) and worse against humans (about 0.15). This is an explanation from the tables, not a separate test.",
      '- CE is dominated by near-zero probabilities (about 5.5 for every mixture against 2.1 for the constant); the exploratory temperature-and-bias head fixes CE (2.14) but not RPS (0.163, worse than the plain mixture).', '',
      '## What was not checked', '',
      '- Only four judge configs exist on both the pool and the 75, so this is a small first check, not a big search. No new inference, no agent search on the pool (version 2), no frontier arm.',
      '- The seventh rater family (Argon) is missing from the checkout; each fresh item has labels from about two families, and the labels of different items come from different families.',
      '- Judge outputs for the 75 here are experiment 106\'s own repeats of the four configs, not the experiment 100 caches used in experiments 10 to 17; I did not compare the two byte for byte.',
      '- The frozen H2 prompt was designed using part of the 75\'s human ratings (experiment 106 report, not rechecked here), so the test is not clean of design-time exposure for the H2 configs. The test has 25 tasks; intervals are wide.',
      '- Rater counts per cell were recounted from the saved cells in this run; the experiment 106 report\'s own numbers (panel agreement with experts, 0.770) were not rechecked.']
open(sys.argv[2], 'w').write('\n'.join(o)+'\n')
